import {matchesStock,selectedStockFeatures,setupStockFeatureControl,renderStockCategories} from '/stock-filters.js';
import {icon} from '/ui-icons.js';
import {renderVehicleCards,renderVehicleDetail} from '/vehicle-markup.js';
import { matchesVehicle, setupLiveSearch } from '/vehicle-search.js';
import { setupWhatsAppClicks } from '/whatsapp-clicks.js';
import { initMotion } from '/site-motion.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(n);
const number=n=>new Intl.NumberFormat('pt-BR').format(n);
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const persist=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value))}catch{}};
const page=document.body.dataset.page,params=new URLSearchParams(location.search);
let featureControl,activeFeatures=selectedStockFeatures(params);
let activeQuery=(params.get('q')||'').trim().slice(0,120);
let cars=[],saved=read('gaspar-favorites',[]),compare=read('gaspar-compare',[]),favoritesOnly=params.get('favoritos')==='1';
if(!Array.isArray(saved))saved=[];if(!Array.isArray(compare))compare=[];
const vehicleUrl=id=>'/veiculo/'+encodeURIComponent(id);
const imageUrl=url=>url.startsWith('assets/')?'/'+url:url;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2800)}
function track(event,data={}){if(read('gaspar-consent',null)==='accepted')window.dataLayer?.push({event,...data})}
function cards(list){return renderVehicleCards(list,{saved,compare})}
function empty(title,text){return `<div class="empty-state"><h3>${title}</h3><p>${text}</p><a class="button dark" href="/estoque">Explorar estoque ${icon('arrow-up-right')}</a></div>`}
function badges(){$('#fav-count').textContent=saved.filter(id=>cars.some(c=>c.id===id)).length;$('#favorites').setAttribute('aria-pressed',favoritesOnly);$('#compare-bar').hidden=compare.length===0||!['home','estoque','veiculo','encontre-seu-carro'].includes(page);$('#compare-count').textContent=compare.length}
function render(){badges();if(!$('#vehicles'))return;let list=cars;
if(page==='estoque'){const filterParams=currentFilters();list=cars.filter(c=>(!favoritesOnly||saved.includes(c.id))&&matchesStock(c,filterParams));featureControl?.update(favoritesOnly?cars.filter(c=>saved.includes(c.id)):cars,filterParams);const sort=$('#sort').value;if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='high')list.sort((a,b)=>b.price-a.price);if(sort==='new')list.sort((a,b)=>b.year-a.year)}else list=cars.slice(0,3);
$('#vehicles').innerHTML=cards(list)||(favoritesOnly?empty('Seus favoritos estão esperando.','Use o coração nos veículos para salvar suas escolhas.'):'<div class="empty-state"><h3>Nenhum veículo com esses filtros.</h3><p>Experimente outras opções ou limpe sua busca.</p><button class="button dark" data-reset>Limpar filtros</button></div>');$('#results-summary').textContent=`${list.length} veículo${list.length===1?'':'s'} ${page==='home'?'em destaque':list.length===1?'encontrado':'encontrados'}${favoritesOnly?' nos favoritos':''}${activeQuery?' para “'+activeQuery+'”':''}.`;
document.querySelectorAll('[data-category]').forEach(b=>{b.classList.toggle('selected',b.dataset.category===$('#category')?.value);b.setAttribute('aria-pressed',b.dataset.category===$('#category')?.value)});if($('.tabs button span'))$('.tabs button span').textContent=String(cars.length).padStart(2,'0');}
function currentFilters(){const query=new URLSearchParams();for(const [id,key]of [['brand','marca'],['price','preco'],['category','categoria'],['sort','ordem']]){const value=$('#'+id)?.value;if(value&&value!=='featured')query.set(key,value)}if(activeQuery)query.set('q',activeQuery);if(favoritesOnly)query.set('favoritos','1');for(const label of activeFeatures)query.append('opcional',label);return query}
function syncFilters(){const query=currentFilters();history.replaceState(null,'','/estoque'+(query.size?'?'+query.toString():''));render()}
function reset(){activeFeatures=[];activeQuery='';if($('#live-search-input'))$('#live-search-input').value='';if($('#live-search-results'))$('#live-search-results').hidden=true;if($('#live-search-input'))$('#live-search-input').setAttribute('aria-expanded','false');favoritesOnly=false;$('#search-form').reset();$('#sort').value='featured';syncFilters()}
if($('#search-form'))$('#search-form').onsubmit=e=>{if(page!=='estoque')return;e.preventDefault();syncFilters();track('search_inventory',{brand:$('#brand').value,category:$('#category').value})};
for(const id of ['brand','price','category','sort'])if($('#'+id)&&page==='estoque')$('#'+id).onchange=syncFilters;
if($('#reset'))$('#reset').onclick=reset;
document.addEventListener('click',e=>{const tab=e.target.closest('[data-category]');if(tab){$('#category').value=tab.dataset.category;syncFilters()}const save=e.target.closest('[data-save]');if(save){const id=save.dataset.save;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];persist('gaspar-favorites',saved);save.classList.toggle('saved',saved.includes(id));save.innerHTML=icon('heart');save.setAttribute('aria-pressed',String(saved.includes(id)));save.setAttribute('aria-label',`${saved.includes(id)?'Remover dos':'Adicionar aos'} favoritos: ${cars.find(c=>c.id===id)?.name||''}`);render();if(page==='encontre-seu-carro'&&$('#quiz-results').children.length)showMatches();}if(e.target.closest('[data-reset]'))reset();const img=e.target.closest('[data-gallery]');if(img){$('#detail-image').src=img.dataset.gallery;$('#detail-image').alt=img.dataset.imageAlt;$('#photo-count').textContent=img.dataset.photoCount;document.querySelectorAll('[data-gallery]').forEach(b=>b.setAttribute('aria-pressed',b===img))}const lead=e.target.closest('[data-lead]');if(lead)track('generate_lead',{vehicle_id:lead.dataset.lead});});
document.addEventListener('change',e=>{if(!e.target.matches('[data-compare]'))return;const id=e.target.dataset.compare;if(e.target.checked){if(compare.length===3){e.target.checked=false;toast('Compare até 3 veículos por vez.');return}if(!compare.includes(id))compare.push(id)}else compare=compare.filter(x=>x!==id);persist('gaspar-compare',compare);badges()});
$('#clear-compare').onclick=()=>{compare=[];persist('gaspar-compare',compare);document.querySelectorAll('[data-compare]').forEach(input=>input.checked=false);render();if(page==='encontre-seu-carro'&&$('#quiz-results').children.length)showMatches()};
$('#favorites').onclick=()=>{location.href='/estoque?favoritos=1'};
$('#menu').onclick=()=>{const open=$('#navlinks').classList.toggle('open');$('#menu').setAttribute('aria-expanded',open);$('#menu').setAttribute('aria-label',open?'Fechar menu':'Abrir menu');$('#menu').innerHTML=icon(open?'close':'menu')};
function renderComparison(){const list=cars.filter(c=>compare.includes(c.id));if(list.length<2){$('#comparison-content').innerHTML=empty('Escolha pelo menos dois veículos.','Marque “Adicionar à comparação” nos modelos que quiser conhecer melhor.');return}const rows=[['Preço',c=>money(c.price)],['Ano',c=>c.year],['Quilometragem',c=>number(c.km)+' km'],['Câmbio',c=>c.transmission],['Combustível',c=>c.fuel],['Categoria',c=>c.category]];$('#comparison-content').innerHTML=`<div class="compare-table"><table><thead><tr><th scope="col">Seu próximo carro</th>${list.map(c=>`<th scope="col"><a href="${vehicleUrl(c.id)}"><img src="${esc(imageUrl(c.images[0]))}" alt="${esc(c.name)}">${esc(c.brand+' '+c.name)}</a><button class="remove-comparison" data-remove-compare="${esc(c.id)}" aria-label="Remover ${esc(c.name)} da comparação">Remover ×</button></th>`).join('')}</tr></thead><tbody>${rows.map(([label,fn])=>`<tr><th scope="row">${label}</th>${list.map(c=>`<td>${esc(fn(c))}</td>`).join('')}</tr>`).join('')}<tr><th scope="row">Próximo passo</th>${list.map(c=>`<td><a class="button dark small" href="${vehicleUrl(c.id)}">Ver veículo ${icon('arrow-up-right')}</a></td>`).join('')}</tr></tbody></table></div>`;track('compare_vehicles',{vehicle_ids:compare})}
document.addEventListener('click',e=>{const remove=e.target.closest('[data-remove-compare]');if(remove){compare=compare.filter(id=>id!==remove.dataset.removeCompare);persist('gaspar-compare',compare);renderComparison();badges()}});
function renderVehicle(){const id=decodeURIComponent(location.pathname.split('/').filter(Boolean).pop());const c=cars.find(c=>c.id===id);if(!c){$('#vehicle-detail').innerHTML=empty('Veículo não encontrado.','Ele pode ter sido removido do estoque. Veja outras possibilidades.');return}$('#vehicle-detail').innerHTML=renderVehicleDetail(c,cars,{saved,compare});track('view_vehicle',{vehicle_id:id,value:c.price,currency:'BRL'})}
function showMatches(){const f=new FormData($('#quiz'));const profile=f.get('profile'),budget=Number(f.get('budget')),gear=f.get('gear');const list=cars.filter(c=>c.price<=budget&&(!gear||c.transmission===gear)).sort((a,b)=>{const rank=c=>profile==='city'?(c.category==='Hatch'?2:0):profile==='family'?(['SUV','Monovolume'].includes(c.category)?2:0):(c.transmission==='Automático'?2:0);return rank(b)-rank(a)||a.price-b.price}).slice(0,3);$('#quiz-results').innerHTML=`<h2>${list.length?'Novos caminhos para você.':'Vamos ampliar os caminhos?'}</h2><p>Sugestões por orçamento, câmbio e categoria. Confirme sua escolha com a equipe.</p><div class="vehicle-grid">${cards(list)||empty('Nenhuma opção com essa combinação.','Tente outras preferências ou explore todo o estoque.')}</div>`;}
if($('#quiz'))$('#quiz').onsubmit=e=>{e.preventDefault();showMatches();$('#quiz-results').scrollIntoView({behavior:'smooth',block:'start'})};
if($('#revoke-consent'))$('#revoke-consent').onclick=()=>{persist('gaspar-consent','rejected');location.reload()};
$('#year').textContent=new Date().getFullYear();
async function init(){const initial=$('#initial-vehicles');let bootstrap;try{bootstrap=initial?JSON.parse(initial.textContent):null}catch{}if(Array.isArray(bootstrap)){cars=bootstrap}else{const response=await fetch('/api/vehicles');if(!response.ok)throw Error('Estoque indisponível.');cars=await response.json()}compare=compare.filter(id=>cars.some(c=>c.id===id)).slice(0,3);persist('gaspar-compare',compare);if($('#brand')){const brands=[...new Set(cars.map(c=>c.brand))].sort();$('#brand').innerHTML='<option value="">Todas as marcas</option>'+brands.map(b=>`<option>${esc(b)}</option>`).join('');const categories=[...new Set(cars.map(c=>c.category))].sort();$('#category').innerHTML='<option value="">Todos os modelos</option>'+categories.map(c=>`<option>${esc(c)}</option>`).join('');if(page==='estoque')for(const [id,key]of [['brand','marca'],['price','preco'],['category','categoria'],['sort','ordem']]){const value=params.get(key);if(value&&Array.from($('#'+id).options).some(o=>o.value===value))$('#'+id).value=value}}
if(page==='estoque'){featureControl=setupStockFeatureControl($('#stock-feature-filters'),values=>{activeFeatures=values;syncFilters()});const tabs=$('.tabs');if(tabs)tabs.innerHTML=renderStockCategories(cars,currentFilters())}
setupLiveSearch(cars);render();if(page==='comparar')renderComparison();if(page==='veiculo')renderVehicle();if(location.hash.startsWith('#veiculo-'))location.replace(vehicleUrl(location.hash.slice(9)));await initTracking()}
initMotion();
init().catch(()=>{const target=$('#vehicles')||$('#vehicle-detail');if(target)target.innerHTML=empty('Não foi possível carregar o estoque.','Recarregue a página ou converse com a equipe.');});

async function initTracking(){let settings;try{const r=await fetch('/api/settings');if(!r.ok)return;settings=await r.json()}catch{return}if(!settings.gtmId&&!settings.metaPixelId)return;const consent=read('gaspar-consent',null);if(consent==='accepted')loadTracking(settings);if(consent===null){const banner=document.createElement('aside');banner.className='cookie-banner';banner.setAttribute('aria-label','Preferências de privacidade');banner.innerHTML='<p>Podemos usar cookies de medição e publicidade para entender visitas e melhorar sua experiência?</p><div><button class="button dark" data-consent="accepted">Aceitar</button><button class="button outline" data-consent="rejected">Recusar</button></div>';document.body.append(banner);banner.onclick=e=>{const choice=e.target.closest('[data-consent]');if(!choice)return;persist('gaspar-consent',choice.dataset.consent);banner.remove();if(choice.dataset.consent==='accepted')loadTracking(settings)}}}
function loadTracking(s){if(window.gasparTrackingLoaded)return;window.gasparTrackingLoaded=true;window.dataLayer=window.dataLayer||[];if(/^GTM-[A-Z0-9]+$/.test(s.gtmId||'')){window.dataLayer.push({'gtm.start':Date.now(),event:'gtm.js'});const script=document.createElement('script');script.async=true;script.src='https://www.googletagmanager.com/gtm.js?id='+s.gtmId;document.head.append(script)}if(/^\d{5,25}$/.test(s.metaPixelId||'')){const fb=window.fbq=function(){fb.callMethod?fb.callMethod.apply(fb,arguments):fb.queue.push(arguments)};fb.queue=[];fb.loaded=true;fb.version='2.0';window._fbq=fb;const script=document.createElement('script');script.async=true;script.src='https://connect.facebook.net/en_US/fbevents.js';document.head.append(script);fb('init',s.metaPixelId);fb('track','PageView')}}


setupWhatsAppClicks();
